import 'dart:ui';
import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_crashlytics/firebase_crashlytics.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'app.dart';
import 'firebase_options.dart';
import 'services/providers.dart';
import 'viewmodels/session_view_model.dart';
import 'services/firebase_messaging_service.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  // Options generated by FlutterFire for the shared PRM393 Firebase project.
  try {
    await Firebase.initializeApp(
        options: DefaultFirebaseOptions.currentPlatform);
  } catch (_) {
    runApp(const MaterialApp(
        home: Scaffold(
            body: Center(
      child: Text('Ứng dụng chưa sẵn sàng. Vui lòng liên hệ nhóm hỗ trợ.'),
    ))));
    return;
  }
  FlutterError.onError = (details) {
    FlutterError.presentError(details);
    FirebaseCrashlytics.instance
        .recordFlutterFatalError(details)
        .catchError((Object _) {});
  };
  PlatformDispatcher.instance.onError = (error, stack) {
    FirebaseCrashlytics.instance
        .recordError(error, stack, fatal: true)
        .catchError((Object _) {});
    return true;
  };
  final container = ProviderContainer(
      overrides: [nativeReminderEventsEnabledProvider.overrideWithValue(true)]);
  container.listen(sessionProvider, (_, next) {
    next.whenData((user) {
      container.read(analyticsServiceProvider).setUserId(user?.uid);
      container.read(crashServiceProvider).setUserId(user?.uid ?? '');
    });
  }, fireImmediately: true);
  try {
    await container.read(remoteConfigServiceProvider).init();
  } catch (error, stack) {
    await container
        .read(crashServiceProvider)
        .recordError(error, stack, reason: 'remote_config_init');
  }
  try {
    await (container.read(messagingServiceProvider) as FirebaseMessagingService)
        .init();
  } catch (error, stack) {
    await container
        .read(crashServiceProvider)
        .recordError(error, stack, reason: 'messaging_init');
  }
  try {
    await container.read(reminderRuntimeProvider).init();
  } catch (error, stack) {
    try {
      await container
          .read(crashServiceProvider)
          .recordError(error, stack, reason: 'local_reminders_init');
    } catch (_) {}
  }
  runApp(UncontrolledProviderScope(
      container: container, child: const AnNhienApp()));
}
